package com.narada.connection

import java.io.OutputStream
import kotlinx.coroutines.*
import org.junit.Assert.*
import org.junit.Test

class TransferExportTest {
    private val tree="content://fixture.documents/tree/root"
    private suspend fun ready():Triple<DownloadFixture,DownloadRecord,TransferExport>{val f=DownloadFixture();val r=f.completed();return Triple(f,r,TransferExport(f.repository,f.engine,f.storage))}
    @Test fun privateReceiptAndIntentPrecedeCreateAndUriPrecedesWrite()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider();p.beforeCreate={assertNotNull(f.record(r.id).receipt);assertEquals(ExportState.INTENT,f.record(r.id).exports.last().state)};p.beforeWrite={assertEquals(ExportState.CREATED,f.record(r.id).exports.last().state);assertEquals(p.uri,f.record(r.id).exports.last().document)};p.beforeRead={assertNotEquals(ExportState.VERIFIED,f.record(r.id).exports.last().state)};e.execute(r.id,request.id,tree,p);assertArrayEquals(f.bytes,p.bytes.toByteArray());assertEquals(ExportState.VERIFIED,f.record(r.id).exports.last().state);assertTrue(p.closed)}
    @Test fun exportRequiresSeparateConsentEvenAfterDownloadConsent()=runBlocking<Unit>{val(f,r,e)=ready();expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{e.prepare(r.id,"copy.bin",false)}};assertTrue(f.record(r.id).exports.isEmpty())}
    @Test fun unverifiedStagingCannotBeExported()=runBlocking<Unit>{val f=DownloadFixture();val r=f.enqueue();val e=TransferExport(f.repository,f.engine,f.storage);expectFailure("TRANSFER_NOT_VERIFIED"){runBlocking{e.prepare(r.id,"copy.bin",true)}}}
    @Test fun missingPrivateBytesBlockBeforeAnyProviderCreation()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);f.storage.data.remove(r.id to 0);val p=FakeDocumentProvider();expectFailure("LOCAL_COPY_MISSING"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(0,p.creates);assertEquals(DownloadState.CORRUPT,f.record(r.id).state);assertEquals(ExportState.NOT_CREATED,f.record(r.id).exports.last().state)}
    @Test fun providerPermissionRefusalIsNotAFileOrTrustReset()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{preflightFailure="PROVIDER_PERMISSION_LOST"};expectFailure("PROVIDER_PERMISSION_LOST"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(0,p.creates);assertEquals(DownloadState.VERIFIED,f.record(r.id).state);assertEquals(ExportState.NOT_CREATED,f.record(r.id).exports.last().state)}
    @Test fun existingNameIsNeverReplacedOrAutomaticallyRenamed()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{preflightFailure="EXPORT_NAME_COLLISION"};expectFailure("EXPORT_NAME_COLLISION"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(0,p.creates);assertEquals(0,p.writes);assertEquals("copy.bin",f.record(r.id).exports.last().name)}
    @Test fun lostCreateReplyStaysUncertainAndCannotBeAutomaticallyRetried()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{createFailure="PROVIDER_CREATE_UNCONFIRMED"};expectFailure("PROVIDER_CREATE_UNCONFIRMED"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(1,p.creates);assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state);assertNull(f.record(r.id).exports.last().document);expectFailure("EXPORT_UNRESOLVED"){runBlocking{e.prepare(r.id,"another.bin",true)}};assertEquals(1,p.creates)}
    @Test fun partialProviderWritePreservesPrivateCopyAndUnknownTarget()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider();val partial=object:NewDocumentProvider by p{override fun writer(document:String):OutputStream=object:OutputStream(){override fun write(b:Int){p.bytes.write(b);fail("PROVIDER_UNAVAILABLE")};override fun write(b:ByteArray,off:Int,len:Int){p.bytes.write(b,off,128);fail("PROVIDER_UNAVAILABLE")}}};expectFailure("PROVIDER_UNAVAILABLE"){runBlocking{e.execute(r.id,request.id,tree,partial)}};assertEquals(128,p.bytes.size());assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state);assertEquals(p.uri,f.record(r.id).exports.last().document);assertEquals(DownloadState.VERIFIED,f.record(r.id).state)}
    @Test fun readbackTamperingNeverBecomesAnExportReceipt()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{readTransform={it.apply{this[0]=0}}};expectFailure("EXPORT_VERIFICATION_FAILED"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state);assertNull(f.record(r.id).exports.last().verifiedAt)}
    @Test fun readbackMustMatchExactLengthIncludingNoTrailingPayload()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{readTransform={it+byteArrayOf(1)}};expectFailure("EXPORT_VERIFICATION_FAILED"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state)}
    @Test fun failedExportReceiptWriteDoesNotInventPublicationSuccess()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);f.beforeWrite={if(it.download(r.id).exports.any{x->x.state==ExportState.VERIFIED})fail("STORAGE_UNAVAILABLE")};val p=FakeDocumentProvider();expectFailure("STORAGE_UNAVAILABLE"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertArrayEquals(f.bytes,p.bytes.toByteArray());assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state);assertEquals(DownloadState.VERIFIED,f.record(r.id).state)}
    @Test fun interruptedPickerCannotAutoCreateAfterProcessRecreation()=runBlocking<Unit>{val(f,r,e)=ready();e.prepare(r.id,"copy.bin",true);f.engine.recover();assertEquals(ExportState.NOT_CREATED,f.record(r.id).exports.last().state);assertEquals(DownloadState.VERIFIED,f.record(r.id).state)}
    @Test fun recoveredCreateIntentIsUncertainAndNotResent()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);f.memory.document=f.memory.document.replaceDownload(f.record(r.id).copy(exports=listOf(request.copy(state=ExportState.INTENT,tree=tree))));f.engine.recover();assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state);val p=FakeDocumentProvider();expectFailure("EXPORT_STOPPED"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(0,p.creates)}
    @Test fun dismissalIsNotCancellationUndoOrSuccess()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{createFailure="PROVIDER_CREATE_UNCONFIRMED"};expectFailure{runBlocking{e.execute(r.id,request.id,tree,p)}};expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{e.dismiss(r.id,request.id,false)}};e.dismiss(r.id,request.id,true);val saved=f.record(r.id).exports.last();assertEquals(ExportState.DISMISSED_UNCONFIRMED,saved.state);assertNull(saved.verifiedAt);e.prepare(r.id,"new-choice.bin",true);assertEquals(1,p.creates)}
    @Test fun deadlineFenceRejectsLateSuccessfulReadback()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{beforeRead={runBlocking{e.interrupted(r.id,request.id)}}};expectFailure("EXPORT_STOPPED"){runBlocking{e.execute(r.id,request.id,tree,p)}};assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state)}
    @Test fun offlineExportOfAnAlreadyReceivedCopyDoesNotGrantNewRemoteAccess()=runBlocking<Unit>{val(f,r,e)=ready();f.pairing.engine.revoke(f.peer.id);f.onChunk={_,_->fail("ACCESS_DENIED")};val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider();e.execute(r.id,request.id,tree,p);assertEquals(ExportState.VERIFIED,f.record(r.id).exports.last().state);assertEquals(TrustStatus.REVOKED,f.memory.document.peer(f.peer.id).status)}
    @Test fun cancellationAfterCreationCannotClaimThatNothingHappened()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);val p=FakeDocumentProvider().apply{beforeWrite={throw CancellationException("fixture interruption")}};try{e.execute(r.id,request.id,tree,p);org.junit.Assert.fail("Expected cancellation")}catch(_:CancellationException){};assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state);assertEquals(1,p.creates);assertEquals(DownloadState.VERIFIED,f.record(r.id).state)}
    @Test fun fullExportHistoryNeverSilentlyEvictsReviewedUnknownOutcomes()=runBlocking<Unit>{val(f,r,e)=ready();val unknown=ExportRecord(java.util.UUID.randomUUID().toString(),"unknown.bin",r.createdAt,ExportState.DISMISSED_UNCONFIRMED);val noFile=ExportRecord(java.util.UUID.randomUUID().toString(),"cancelled.bin",r.createdAt,ExportState.NOT_CREATED);f.memory.document=f.memory.document.replaceDownload(r.copy(exports=listOf(unknown,noFile)));expectFailure("EXPORT_HISTORY_FULL"){runBlocking{e.prepare(r.id,"new.bin",true)}};assertEquals(listOf(unknown,noFile),f.record(r.id).exports);expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{e.forget(r.id,unknown.id,false)}};e.forget(r.id,unknown.id,true);assertEquals(listOf(noFile),f.record(r.id).exports);assertNotNull(f.record(r.id).receipt);e.prepare(r.id,"new.bin",true)}
    @Test fun unreviewedUncertaintyCannotBeRemovedAsAReceipt()=runBlocking<Unit>{val(f,r,e)=ready();val request=e.prepare(r.id,"copy.bin",true);expectFailure{runBlocking{e.execute(r.id,request.id,tree,FakeDocumentProvider().apply{createFailure="PROVIDER_CREATE_UNCONFIRMED"})}};expectFailure("EXPORT_UNRESOLVED"){runBlocking{e.forget(r.id,request.id,true)}};assertEquals(ExportState.UNCERTAIN,f.record(r.id).exports.last().state)}

}
